import{_ as i,o as e,c as a,ae as t}from"./chunks/framework.EHGTsUvI.js";const p="/assets/eventLoop-1.I7oLrZ2C.gif",n="/assets/eventLoop-2.BMMrQc5j.gif",l="/assets/eventLoop-3.CYdN6n0M.gif",o="/assets/eventLoop-4.Bz0FSfwp.gif",h="/assets/eventLoop-5.2jb1s33i.gif",k="/assets/eventLoop-6.BxCgaYE7.gif",F=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"translation/devto-jseventloop.md","filePath":"translation/devto-jseventloop.md"}'),r={name:"translation/devto-jseventloop.md"};function d(m,s,g,E,c,y){return e(),a("div",null,[...s[0]||(s[0]=[t('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>本篇文章是怀着赞许与尊敬从<a href="https://dev.to/lydiahallie" target="_blank" rel="noreferrer">Lydia Hallie</a>的文章中翻译而来的，<a href="https://dev.to/lydiahallie/javascript-visualized-event-loop-3dif" target="_blank" rel="noreferrer">原文</a>比这精彩地多</p></div><p>事件循环(Event loop)是JavaScript开发人员避不开的一件事，一开始理解起来可能有点困惑(反正我是挺困惑的)。原作者Lydia Hallie是个视觉学习者，以下所有的gif都是她做的，非常生动。</p><p>首先，什么是事件循环，你为什么需要了解它？</p><p>众所周知，JavaScript是单线程的 : 一次只能运行一个任务。通常来说好像没什么大不了的。但想象一下，你正在运行一项耗时30秒的任务，是的，这个任务耗时30秒，然后才能运行其他任务(默认情况下，JavaScript在浏览器的主线程上运行，因此整个UI界面就“咔”地卡住了)，现在都1202年了，没有人想要一个速度慢、反应迟钝的网站。</p><p>幸运的是，浏览器为我们提供了JavaScript引擎本身不提供的一些功能：Web API。其中包括 <strong>setTimeout</strong>, DOM API, HTTP API等等。这可以帮助我们创建一些异步，非阻塞行为。</p><p>当我们调用一个函数时，它会被添加进 <em>调用栈</em> (call stack)里,调用栈是JS引擎的一部分，不是特定于浏览器的，栈是<strong>先进后出</strong>的。当函数返回了值之后，这个函数就会从栈中弹出。</p><p><img src="'+p+'" alt="eventLoop-1"></p><p>这里先是<em>greet</em>函数被推进调用栈里，然后返回“Hello”，<strong>当函数返回值了之后，就会从栈中弹出</strong>，因此 <em>greet</em> 函数被弹出栈。然后往下执行到 <em>respond</em> 函数， <em>respond</em> 函数返回一个 <em>setTimeout函数</em>， 因为这是栈，先进后出，所以会先把 <em>setTimeout</em> 函数弹出栈再弹出 <em>respond</em> , <em>setTimeout</em> 函数是由Web API提供的，它让我们在不阻塞主线程的情况下延迟执行任务。我们传递给 <em>setTimeout</em> 的回调函数：箭头函数 <code>() =&gt; {return &#39;Hey&#39;}</code> 被添加到Web API. 与此同时， <em>setTimeout</em> 函数和 <em>respond</em> 函数从堆栈中弹出，它们都返回了自己的值！</p><p><img src="'+n+'" alt="eventLoop-2"></p><p>在Web API中，有一个计时器，它的运行时间和我们传递给它的第二个参数 1000ms 一样长。回调不会立即添加到调用堆栈中，而是传递给称为<em><strong>队列</strong></em>的东西。</p><p><img src="'+l+'" alt="eventLoop-3"></p><p>这可能是令人困惑的部分：这并不意味着回调函数在1000ms之后被添加到调用栈之中(因此返回值)，尽管若没有上面这张图，看起来就像这样，但是并不是，队列在其中也有它的戏份。而是在1000ms之后回调函数会被添加进 <em>队列</em> 。但这是一个队列，函数必须等待被执行。</p><p>接下来就来到了我们一直等待的部分..是时候让<em>事件循环</em>(Event Loop)完成其唯一的任务了：*<em>将队列与调用栈联系起来！<em>如果调用栈是空的，也就是说之前所有被调用的函数都已经返回了他们的值并且已经被弹出了调用栈，那么队列中的</em>第一项</em> 将被添加进调用栈中。在这种情况下，没有调用任何其他函数，这意味着当回调函数是队列中的第一个项目时，调用堆栈为空。</p><p><img src="'+o+'" alt="eventLoop-4"></p><p>回调函数被添加进调用栈，被调用并返回一个值，然后从堆栈中弹出。<img src="'+h+`" alt="eventLoop-5"></p><p>事件循环的整体思想就介绍完了。整理一下就是：**同步执行的函数被运行时会被立刻推进调用栈中，然后执行函数，返回值，最后从调用栈中被弹出。而异步函数会被添加进Web API中，等待设置的时间后会进入队列，一直等待，直到调用栈为空，然后被推入调用栈，返回值，从堆栈中弹出。**接下里看一个例子，运行之前先想想会输出什么结果。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> foo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;First&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> setTimeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Second&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> baz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Third&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">baz</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>让我们来看看在浏览器运行这段代码时发生了什么：</p><p><img src="`+k+`" alt="eventLoop-6"></p><ol><li>我们调用了 <em>bar</em> 函数。<em>bar</em> 函数返回一个 <em>setTimeout</em> 函数</li><li>我们传给 <em>setTimeout</em> 的回调函数被添加进Web API, <em>setTimeout</em> 函数和 <em>bar</em> 被弹出堆栈</li><li>Web API中的计时器在计时的同时， <em>foo</em> 函数被调用并输出 &quot;First&quot;. <em>foo</em> 返回(undefined), <em>baz</em> 被调用，回调函数进入队列</li><li><em>baz</em> 输出 ”Third“. 事件循环在 <em>baz</em> 返回值后发现堆栈是空的，于是此时回调函数被添加进堆栈</li><li>堆栈输出 “Second”</li></ol><p>于是我们最终得到的结果是:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Third</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Second</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>翻译中添加了一下我自己的理解，并不是完全按照原文翻译的，可能有语句不通或者理解不准确的情况，详细文章可以移步<a href="https://dev.to/lydiahallie/javascript-visualized-event-loop-3dif" target="_blank" rel="noreferrer">原作者的文章</a>。</p></div>`,23)])])}const u=i(r,[["render",d]]);export{F as __pageData,u as default};
